#include <stdio.h>

/* teste do desafio o-procurador — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nada de captura de tela. Cada cenario monta a lista, chama a
   funcao do aluno e confere o numero devolvido. Os tres cenarios cobrem o
   valor no meio, o valor ausente e o valor na gaveta 0 — o caso que o
   -1 nao pode confundir. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int procurar(int v[], int n, int x);

SM_TEST(acha_no_meio_da_lista) {
    int notas[4] = {7, 2, 9, 4};
    checa_int("a posicao do 9", procurar(notas, 4, 9), 2,
              "o 9 esta na terceira gaveta, e a terceira gaveta e o indice 2");
}

SM_TEST(nao_acha_e_devolve_menos_um) {
    int notas[4] = {7, 2, 9, 4};
    checa_int("o aviso de nao achei", procurar(notas, 4, 5), -1,
              "nenhuma gaveta guarda o 5: o laco acaba e a funcao devolve -1");
}

SM_TEST(acha_na_gaveta_zero) {
    int notas[4] = {7, 2, 9, 4};
    checa_int("a posicao do 7", procurar(notas, 4, 7), 0,
              "o 7 abre a lista: a resposta e 0, e 0 nao quer dizer nao achei");
}

solutionCode:
#include <stdio.h>

int procurar(int v[], int n, int x) {
    for (int i = 0; i < n; i++) {
        if (v[i] == x) {
            return i;
        }
    }
    return -1;
}
